components.css:
.ds-btn-primary { background: oklch(0.72 0.135 70); color: oklch(0.21 0.012 60); border: 1px solid transparent; border-radius: 8px; padding: 8px 16px; font-family: ui-sans-serif, system-ui, -apple-system, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif; font-size: 0.875rem; font-weight: 500; width: 100%; cursor: pointer; transition: background-color 0.15s ease; }
.ds-btn-primary:hover { background: oklch(0.66 0.135 70); }
.ds-btn-primary:focus-visible { outline: none; box-shadow: 0 0 0 2px oklch(0.22 0.012 60), 0 0 0 4px oklch(0.72 0.135 70); }
.ds-btn-primary:disabled { opacity: 0.6; cursor: default; }

.ds-btn-secondary { background: oklch(0.27 0.015 60); color: oklch(0.95 0.01 80); border: 1px solid oklch(0.35 0.016 65); border-radius: 8px; padding: 8px 16px; font-family: ui-sans-serif, system-ui, -apple-system, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif; font-size: 0.875rem; font-weight: 500; cursor: pointer; transition: border-color 0.15s ease, background-color 0.15s ease; }
.ds-btn-secondary:hover { border-color: oklch(0.66 0.135 70); }
.ds-btn-secondary:focus-visible { outline: none; box-shadow: 0 0 0 2px oklch(0.22 0.012 60), 0 0 0 4px oklch(0.72 0.135 70); }

.ds-field-label { display: block; margin-bottom: 4px; font-family: ui-sans-serif, system-ui, -apple-system, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif; font-size: 0.875rem; font-weight: 500; color: oklch(0.95 0.01 80); }
.ds-field-input { width: 100%; box-sizing: border-box; background: oklch(0.22 0.012 60); color: oklch(0.95 0.01 80); border: 1px solid oklch(0.35 0.016 65); border-radius: 8px; padding: 8px 12px; font-family: ui-sans-serif, system-ui, -apple-system, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif; font-size: 0.875rem; }
.ds-field-input::placeholder { color: oklch(0.7 0.02 70); }
.ds-field-input:focus { outline: none; border-color: oklch(0.72 0.135 70); }
.ds-field-input:focus-visible { outline: none; box-shadow: 0 0 0 2px oklch(0.22 0.012 60), 0 0 0 4px oklch(0.72 0.135 70); }
.ds-field-error { margin-top: 4px; font-family: ui-sans-serif, system-ui, -apple-system, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif; font-size: 0.875rem; color: oklch(0.72 0.15 25); }

.ds-field-label { display: block; margin-bottom: 4px; font-family: ui-sans-serif, system-ui, -apple-system, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif; font-size: 0.875rem; font-weight: 500; color: oklch(0.95 0.01 80); }
.ds-phone-group { display: flex; align-items: center; background: oklch(0.22 0.012 60); border: 1px solid oklch(0.35 0.016 65); border-radius: 8px; transition: border-color 0.15s ease; }
.ds-phone-group:focus-within { border-color: oklch(0.72 0.135 70); }
.ds-phone-group[data-invalid="true"] { border-color: oklch(0.72 0.15 25); }
.ds-phone-addon { flex: none; border-right: 1px solid oklch(0.35 0.016 65); padding: 8px 12px; font-family: ui-sans-serif, system-ui, -apple-system, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif; font-size: 0.875rem; color: oklch(0.7 0.02 70); }
.ds-phone-input { flex: 1; min-width: 0; background: transparent; color: oklch(0.95 0.01 80); border: none; padding: 8px 12px; font-family: ui-sans-serif, system-ui, -apple-system, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif; font-size: 0.875rem; }
.ds-phone-input::placeholder { color: oklch(0.7 0.02 70); }
.ds-phone-input:focus { outline: none; }

.ds-card { background: oklch(0.27 0.015 60); border: 1px solid oklch(0.35 0.016 65); border-radius: 16px; box-shadow: 0 1px 2px oklch(0.1 0.015 60 / 0.4), 0 12px 32px oklch(0.06 0.01 60 / 0.45); max-width: 384px; }
.ds-card-head { padding: 24px 24px 0; }
.ds-card-title { margin: 0; font-family: ui-sans-serif, system-ui, -apple-system, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif; font-size: 1.5rem; font-weight: 600; letter-spacing: -0.025em; color: oklch(0.95 0.01 80); }
.ds-card-sub { margin: 6px 0 0; font-family: ui-sans-serif, system-ui, -apple-system, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif; font-size: 0.875rem; color: oklch(0.7 0.02 70); }
.ds-tear { margin: 20px 24px 0; border-top: 1px dashed oklch(0.35 0.016 65); }
.ds-card-body { padding: 20px 24px 24px; display: flex; flex-direction: column; gap: 20px; }

.ds-ticket { background: oklch(0.27 0.015 60); border: 1px solid oklch(0.35 0.016 65); border-radius: 16px; box-shadow: 0 1px 2px oklch(0.1 0.015 60 / 0.4), 0 12px 32px oklch(0.06 0.01 60 / 0.45); max-width: 384px; }
.ds-ticket-body { text-align: center; padding: 32px 24px 8px; }
.ds-ticket-number { margin: 0; font-family: ui-sans-serif, system-ui, -apple-system, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif; font-size: 5.5rem; font-weight: 600; line-height: 1; letter-spacing: -0.025em; color: oklch(0.95 0.01 80); }
.ds-ticket-status { margin: 24px 0 0; font-family: ui-sans-serif, system-ui, -apple-system, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif; font-size: 1.125rem; font-weight: 500; color: oklch(0.95 0.01 80); }
.ds-ticket-eta { margin: 4px 0 0; font-family: ui-sans-serif, system-ui, -apple-system, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif; font-size: 0.875rem; color: oklch(0.7 0.02 70); }
.ds-tear { margin: 24px; border-top: 1px dashed oklch(0.35 0.016 65); }
.ds-ticket-foot { display: flex; justify-content: space-between; padding: 0 24px 24px; font-family: ui-sans-serif, system-ui, -apple-system, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif; font-size: 0.75rem; color: oklch(0.7 0.02 70); }

.ds-ticket { background: oklch(0.27 0.015 60); border: 1px solid oklch(0.35 0.016 65); border-radius: 16px; box-shadow: 0 1px 2px oklch(0.1 0.015 60 / 0.4), 0 12px 32px oklch(0.06 0.01 60 / 0.45); max-width: 384px; }
.ds-ticket-notified { border-color: oklch(0.72 0.135 70); animation: ds-ticket-warm 0.7s cubic-bezier(0.16, 1, 0.3, 1) both; }
@keyframes ds-ticket-warm { from { opacity: 0.55; transform: scale(0.985); } to { opacity: 1; transform: scale(1); } }
